/* n 是零基编号下标；先将两个初值分别对正 modulus 取余。 */
#include <stdio.h>
int main(void)  {
    long long n, a, b, modulus;
    scanf("%lld%lld%lld%lld", &n, &a, &b, &modulus);
    a %= modulus;
    b %= modulus;
    /* next 必须用旧 a、b 求和，再平移为旧 b 和 next，始终只保留两项。 */
    for (long long i = 1; i < n; i++)  {
        long long next = (a + b) % modulus;
        a = b;
        b = next;
    }
    /* n=0 输出第一个初值余数，其余下标输出迭代结束后的 b。 */
    printf("%lld\n", n == 0 ? a : b);
    return 0;
}

